function findRealFacilities(province, city, district, street, category) {
  province = province || '';
  city = (city || '').replace(/市$/, '');
  district = district || '';
  street = street || '';
  category = category || '';

  try {
    if (!city || !FACILITIES_DATA[city]) {
      return [];
    }
    if (!district || !FACILITIES_DATA[city][district]) {
      return [];
    }
    if (!street || !FACILITIES_DATA[city][district][street]) {
      return [];
    }
    if (!category || !FACILITIES_DATA[city][district][street][category]) {
      return [];
    }
    return FACILITIES_DATA[city][district][street][category];
  } catch (e) {
    return [];
  }
}